const express = require('express');
const { SQSClient, DeleteMessageCommand } = require('@aws-sdk/client-sqs');
const { TaskTracker } = require('../models/taskTracker');

const app = express();
app.use(express.json());

const sqs = new SQSClient({ region: 'us-east-2' });
const TASK_QUEUE_URL = process.env.ASYNC_TASK_QUEUE_URL;

app.delete('/api/async-jobs/queue/:receiptHandle', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { receiptHandle } = req.params;
  const decodedHandle = decodeURIComponent(receiptHandle);

  // Verify ownership of the queued task prior to deleting from SQS
  const task = await TaskTracker.findOne({
    where: {
      receiptHandle: decodedHandle,
      creatorUserId: req.user.id
    }
  });

  if (!task) {
    return res.status(403).json({ error: 'Access denied: task not found or owned by another user' });
  }

  const deleteCmd = new DeleteMessageCommand({
    QueueUrl: TASK_QUEUE_URL,
    ReceiptHandle: decodedHandle
  });

  try {
    await sqs.send(deleteCmd);
    await TaskTracker.update({ status: 'CANCELLED' }, { where: { id: task.id } });
    res.json({ status: 'CANCELLED_AND_PURGED' });
  } catch (err) {
    res.status(500).json({ error: 'Failed to purge SQS task message' });
  }
});

app.listen(3007);
